/**
 * api/types.ts: short names for the loan API's data types.
 *
 * Where it sits: backend (Pydantic models) -> openapi.json -> schema.d.ts (generated)
 * -> [types.ts] -> every component that reads API data.
 *
 * BUSINESS: the KPI tiles and the grid read exactly the fields the API sends.
 * TECH: schema.d.ts is generated by `npm run gen:api` (openapi-typescript) and must
 *   never be edited. This file only gives its types friendlier names, so no API
 *   type is written by hand (.claude/rules/frontend.md).
 */
import type { components } from "./schema";

/** One tape column. BUSINESS: a grid header. TECH: kind is text | number | date | boolean. */
export type ColumnInfo = components["schemas"]["ColumnInfo"];
/** One page of loans. TECH: total counts every loan matching the filter, not just this page. */
export type LoansPage = components["schemas"]["LoansPage"];
/** The tape's headline numbers, weighted by current UPB. */
export type Summary = components["schemas"]["Summary"];
/** One loan row. TECH: the API sends rows as column name -> value (dict[str, Any]). */
export type LoanRow = LoansPage["rows"][number];
